/* Generated by sitereal. The connection, and nothing else.

   Both values are read from the environment by name — nothing about your
   database is stored in the project file, which is committed. A local
   `file:./local.db` needs no token at all, which is the quickest way to try
   this before there is anything hosted to point at. */
import { drizzle } from 'drizzle-orm/libsql';
import { createClient } from '@libsql/client';

const url = (typeof import.meta.env === 'undefined' ? undefined : import.meta.env.SITEREAL_DB_URL) ?? process.env.SITEREAL_DB_URL;
if (!url) throw new Error('SITEREAL_DB_URL is not set — see .env.example');

export const client = createClient({
  url,
  authToken: (typeof import.meta.env === 'undefined' ? undefined : import.meta.env.SITEREAL_DB_TOKEN) ?? process.env.SITEREAL_DB_TOKEN,
});

export const db = drizzle(client);
export * from './schema';

import { team as teamTable } from './schema';

const entrySlugify = (s: unknown) => String(s).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
/** The row's slug as the site spells it: the one it was given, else its title, else its id. */
const entrySlugOf = (r: { slug?: unknown; title?: unknown }, id: unknown) => String(r.slug ?? '').split('/').map(entrySlugify).filter(Boolean).join('/')
  || entrySlugify(String(r.title ?? '')) || String(id);

/** Every live Team row, oldest first — what a Loop over it repeats. */
export async function teamRows() {
  const rows = (await db.select().from(teamTable).orderBy(teamTable.createdAt, teamTable.id)).filter((r) => r.status !== 'draft');
  return rows.map((r) => ({
    ...r,
    slug: entrySlugOf(r, r.id),
  }));
}
